import {linkPicker,mountLinkPreview,chainIcon} from './page-links.js';
import {pageTargets} from './document-links.js';
import {world} from './store.js';
import {sanitize,escapeHTML as e,plain} from './store.js';
const marker='<!--aethra-rich-->';
export const richText=value=>String(value||'').startsWith(marker)?sanitize(String(value).slice(marker.length)):e(value||'').replaceAll('\n','<br>');
export const textValue=value=>String(value||'').startsWith(marker)?plain(String(value).slice(marker.length)):String(value||'');
const presets=[['h1','Título'],['h2','Subtítulo'],['h3','Seção'],['strong','Forte'],['p','Corpo'],['small','Legenda']];
function presetMarkup(){return `<h3>Formato</h3><small class="format-caption">TEXTO</small><div class="format-presets">${presets.map(([tag,label])=>`<button type="button" data-text-preset="${tag}">${label}</button>`).join('')}</div>`;}
function decorateEditor(toolbar){
 if(toolbar.dataset.formatReady)return;toolbar.dataset.formatReady='true';toolbar.classList.add('format-drawer','note-format-panel');
 const note=toolbar.closest('.note-editor'),head=note.querySelector('.note-editor-head');
 const button=document.createElement('button');button.type='button';button.className='format-launch';button.textContent='Aa · Formato';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','noteFormatPanel');head.append(button);toolbar.id='noteFormatPanel';
 const nodes=[...note.children].filter(el=>el!==head&&el!==toolbar),body=document.createElement('div'),writing=document.createElement('div');body.className='note-body-layout';writing.className='note-writing-surface';nodes.forEach(el=>writing.append(el));body.append(writing,toolbar);note.append(body);
 const stash=document.createElement('div');while(toolbar.firstChild)stash.append(toolbar.firstChild);
 toolbar.innerHTML='<div class="note-format-heading"><div><span class="eyebrow">VOTRE ATELIER</span><h3>Formatação</h3></div><button type="button" class="note-format-close" aria-label="Fechar formatação">×</button></div><p class="note-format-help">Selecione um trecho ou posicione o cursor no parágrafo.</p>';
 toolbar.querySelector('.eyebrow').textContent='SEU ATELIÊ DE ESCRITA';
 function group(title,selectors,cls=''){const section=document.createElement('section');section.className='note-format-group '+cls;section.innerHTML=`<h4>${title}</h4><div class="note-format-controls"></div>`;for(const selector of selectors){const el=stash.querySelector(selector);if(el)section.lastElementChild.append(el);}toolbar.append(section);return section;}
 const styles=group('Estilo do parágrafo',[],'note-style-section');styles.lastElementChild.innerHTML=presets.filter(([tag])=>tag!=='strong').map(([tag,label])=>`<button type="button" data-text-preset="${tag}" aria-pressed="false">${label}</button>`).join('');
 group('Tipografia',['#fontFamily','#fontSize'],'note-font-section');
 group('Ênfase',['[data-format=bold]','[data-format=italic]','[data-format=underline]','[data-format=strikeThrough]','[data-format=superscript]','[data-format=subscript]','#inlineCode']);
 group('Alinhamento',['[data-format=justifyLeft]','[data-format=justifyCenter]','[data-format=justifyRight]','[data-format=justifyFull]']);
 group('Listas e recuos',['[data-format=insertUnorderedList]','[data-format=insertOrderedList]','#checklistButton','[data-format=indent]','[data-format=outdent]']);
 group('Cores',['#colorPicker','#highlightButton'],'note-color-section');
 group('Espaçamento e inserção',['#lineSpacing','#linkButton','[data-block=blockquote]','#separatorButton']);
 const advanced=document.createElement('details');advanced.className='note-format-advanced';advanced.innerHTML='<summary>Mais opções</summary>';toolbar.append(advanced);const extra=group('Transformar e limpar',['[data-case=upper]','[data-case=lower]','#clearFormatting']);advanced.append(extra);
 const footer=group('Histórico',['[data-format=undo]','[data-format=redo]'],'note-history-section');
 const block=stash.querySelector('#blockType');block.hidden=true;toolbar.append(block);
 const close=()=>{toolbar.classList.remove('format-open');note.classList.remove('formatting-visible');button.setAttribute('aria-expanded','false');toolbar.querySelector('#colorPicker').open=false;};
 button.addEventListener('pointerdown',ev=>ev.preventDefault());button.onclick=()=>{if(toolbar.classList.contains('format-open'))close();else{toolbar.classList.add('format-open');note.classList.add('formatting-visible');button.setAttribute('aria-expanded','true');}};
 toolbar.querySelector('.note-format-close').onclick=close;
 toolbar.querySelectorAll('[data-text-preset]').forEach(b=>b.onclick=()=>toolbar.dispatchEvent(new CustomEvent('editor-preset',{detail:b.dataset.textPreset})));
 toolbar.addEventListener('keydown',ev=>{if(ev.key==='Escape'){ev.preventDefault();ev.stopPropagation();close();button.focus();}});
 note.querySelector('#readMode').addEventListener('click',close);
}
function enhanceField(textarea){
 if(textarea.dataset.formatReady)return;textarea.dataset.formatReady='true';
 const wrap=document.createElement('div');wrap.className='rich-field';
 const name=textarea.closest('label')?.querySelector('span')?.textContent||'Texto';
 wrap.innerHTML=`<div class="rich-field-top"><span>Texto com formatação</span><button type="button" class="format-launch" aria-expanded="false">Aa · Formato</button></div><div class="field-format-panel" hidden>${presetMarkup()}<small class="format-caption">ESTILO E PARÁGRAFO</small><div class="format-commands">${[['bold','B'],['italic','I'],['underline','U'],['strikeThrough','S̶'],['insertUnorderedList','• Lista'],['insertOrderedList','1. Lista'],['justifyLeft','Esquerda'],['justifyCenter','Centro'],['justifyRight','Direita'],['justifyFull','Justificar'],['indent','Recuar +'],['outdent','Recuar −'],['removeFormat','Limpar'],['undo','↶'],['redo','↷']].map(([cmd,label])=>`<button type="button" data-command="${cmd}" title="${cmd}">${label}</button>`).join('')}</div><small class="format-caption">DECORAÇÕES</small><div class="format-commands"><button type="button" data-block="blockquote">Citação / foco</button><button type="button" data-inline="code">Código</button><button type="button" data-highlight>Marca-texto</button></div><small class="format-caption">COR</small><div class="format-swatches">${['#3c4542','#6a7b78','#a09c94','#3458a2','#6c5b96','#4b7657','#b39354','#bc7279'].map(c=>`<button type="button" data-swatch="${c}" style="background:${c}" aria-label="Cor ${c}"></button>`).join('')}<input type="color" value="#b39354" aria-label="Personalizar cor do texto"></div><label class="format-font">Fonte<select aria-label="Fonte do campo"><option value="inherit">Padrão do tema</option><option value="Georgia">Serif</option><option value="Arial">Sans</option><option value="Courier New">Mono</option></select></label></div><div class="rich-field-content" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${e(name)}">${richText(textarea.value)}</div>`;
 textarea.hidden=true;const label=textarea.closest('label.field');if(label)label.after(wrap);else textarea.after(wrap);const input=wrap.querySelector('.rich-field-content'),panel=wrap.querySelector('.field-format-panel'),toggle=wrap.querySelector('.format-launch');let range=null;
 const expand=document.createElement('button');expand.type='button';expand.className='field-expand';expand.textContent='⛶ Expandir';expand.setAttribute('aria-expanded','false');wrap.querySelector('.rich-field-top').append(expand);expand.onpointerdown=ev=>{capture();ev.preventDefault();};expand.onclick=()=>{const open=wrap.classList.toggle('rich-field-expanded');expand.textContent=open?'⛶ Restaurar':'⛶ Expandir';expand.setAttribute('aria-expanded',String(open));};
 const link=document.createElement('button');link.type='button';link.className='rich-field-link';link.innerHTML=chainIcon;link.title='Adicionar ou editar link';link.setAttribute('aria-label',link.title);wrap.querySelector('.rich-field-top').append(link);
 link.onpointerdown=ev=>{capture();ev.preventDefault();};link.onclick=()=>{restore();capture();const s=getSelection(),candidate=(s.anchorNode?.nodeType===1?s.anchorNode:s.anchorNode?.parentElement)?.closest('a'),anchor=candidate&&input.contains(candidate)?candidate:null;if(anchor){range=document.createRange();range.selectNode(anchor);}linkPicker({documents:pageTargets(world()),anchor,selected:anchor?.textContent||s.toString(),onInsert:html=>command('insertHTML',html),onRemove:()=>command('unlink'),onClose:restore});};
 const openPage=id=>document.dispatchEvent(new CustomEvent('aethra:open-page',{detail:id}));const disposePreview=mountLinkPreview(input,pageTargets(world()),openPage);const owner=textarea.closest('dialog');owner?.addEventListener('close',disposePreview,{once:true});input.addEventListener('click',ev=>{const a=ev.target.closest('a');if(!a)return;ev.preventDefault();if((ev.ctrlKey||ev.metaKey)&&a.getAttribute('href')?.startsWith('#document/'))openPage(decodeURIComponent(a.getAttribute('href').slice(10)));});
 const sync=()=>{textarea.value=marker+sanitize(input.innerHTML);textarea.dispatchEvent(new Event('input',{bubbles:true}));};
 const capture=()=>{const s=getSelection();if(s.rangeCount&&input.contains(s.getRangeAt(0).commonAncestorContainer))range=s.getRangeAt(0).cloneRange();};
 input.addEventListener('keyup',capture);input.addEventListener('pointerup',capture);input.addEventListener('input',()=>{capture();sync();});
 function restore(){input.focus({preventScroll:true});const s=getSelection();if(range&&input.contains(range.commonAncestorContainer)){s.removeAllRanges();s.addRange(range);}else{const r=document.createRange();r.selectNodeContents(input);r.collapse(false);s.removeAllRanges();s.addRange(r);}}
 function command(cmd,value){restore();document.execCommand('styleWithCSS',false,true);document.execCommand(cmd,false,value);capture();sync();}
 toggle.onpointerdown=ev=>{capture();ev.preventDefault();};toggle.onclick=()=>{panel.hidden=!panel.hidden;wrap.classList.toggle('field-format-open',!panel.hidden);toggle.setAttribute('aria-expanded',String(!panel.hidden));};
 panel.onpointerdown=ev=>{capture();if(ev.target.closest('button'))ev.preventDefault();};
 panel.onclick=ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.command)command(b.dataset.command);if(b.dataset.textPreset){const tag=b.dataset.textPreset;if(tag==='strong')command('bold');else{command('formatBlock',tag==='small'?'p':tag);if(tag==='small')style('font-size','11px');}}if(b.dataset.swatch)style('color',b.dataset.swatch);if(b.dataset.block)command('formatBlock','blockquote');if(b.dataset.inline)style('font-family','monospace');if(b.hasAttribute('data-highlight'))style('background-color','#e0c58f');};
 function style(property,value){restore();const s=getSelection(),r=s.getRangeAt(0);if(r.collapsed){if(property==='color')document.execCommand('foreColor',false,value);else if(property==='background-color')document.execCommand('hiliteColor',false,value);else{input.style.setProperty(property,value);const span=document.createElement('span');span.style.setProperty(property,value);span.innerHTML=input.innerHTML;input.replaceChildren(span);} }else{const span=document.createElement('span');span.style.setProperty(property,value);span.append(r.extractContents());r.insertNode(span);r.selectNodeContents(span);s.removeAllRanges();s.addRange(r);}capture();sync();}
 panel.querySelector('input[type=color]').oninput=ev=>style('color',ev.target.value);panel.querySelector('select').onchange=ev=>style('font-family',ev.target.value==='inherit'?'serif':ev.target.value);
 input.onpaste=ev=>{ev.preventDefault();command('insertHTML',sanitize(ev.clipboardData.getData('text/html')||e(ev.clipboardData.getData('text/plain')).replaceAll('\n','<br>')));};
 textarea.form?.addEventListener('submit',()=>{if(!textarea.value.startsWith(marker)&&input.textContent.trim())sync();},true);
}
export function initFormatting(){
 const prosePreviews=new Map();let queued=false;const scan=()=>{queued=false;for(const [el,dispose] of prosePreviews)if(!el.isConnected){dispose();prosePreviews.delete(el);}document.querySelectorAll('.rich-prose').forEach(el=>{if(prosePreviews.has(el))return;const open=id=>document.dispatchEvent(new CustomEvent('aethra:open-page',{detail:id}));prosePreviews.set(el,mountLinkPreview(el,pageTargets(world()),open));el.addEventListener('click',ev=>{const a=ev.target.closest('a');if(a?.getAttribute('href')?.startsWith('#document/')){ev.preventDefault();try{open(decodeURIComponent(a.getAttribute('href').slice(10)));}catch{}}});});document.querySelectorAll('.editor-toolbar:not([data-format-ready])').forEach(decorateEditor);document.querySelectorAll('textarea:not([data-format-ready])').forEach(t=>{if(['description','motivation','conflict'].includes(t.name)||t.dataset.rich||t.name.startsWith('beast_'))enhanceField(t);});};
 new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(scan);}}).observe(document.body,{childList:true,subtree:true});scan();
 document.addEventListener('pointerdown',ev=>{document.querySelectorAll('.field-format-panel:not([hidden])').forEach(p=>{if(!p.parentElement.contains(ev.target)){p.hidden=true;p.parentElement.classList.remove('field-format-open');p.parentElement.querySelector('.format-launch').setAttribute('aria-expanded','false');}});});
}
